// app/screens/Training/QuizAssignSlide.tsx
import { demoQuizAssign } from "@/app/data/demoQuizAssign";
import { getImageByKey, imageMap } from "@/app/utils/imageMappings";

import {
  dynamicIconSize,
  dynamicSpacing,
  isTablet,
  scaleFont,
  useOrientation,
} from "@/app/utils/responsive";
import type React from "react";
import { useEffect, useState } from "react";
import {
  Image,
  ScrollView,
  StyleSheet,
  Text,
  TouchableOpacity,
  View,
} from "react-native";
import { useTheme } from "../context/ThemeContext";
import { hyphenateLabel } from "../utils/hyphenateLabel";

interface QuizAssignSlideProps {
  quizId: number;
  selected: string | null;
  onSelect: (v: string | null) => void;
  confirmRequested: boolean;
  onConfirmed: () => void;
  onResult: (correctCount: number, totalCount: number) => void;
  onFeedback: (text: string) => void;
  setUndoElement: (element: React.ReactNode) => void;
  externalShowSolutions?: boolean;
}

export default function QuizAssignSlide({
  quizId,
  selected,
  onSelect,
  confirmRequested,
  onConfirmed,
  onResult,
  onFeedback,
  setUndoElement,
  externalShowSolutions,
}: QuizAssignSlideProps) {
  const { theme } = useTheme();
  const isDarkMode = theme.dark === true;

  // Quizdaten + Zuordnungsstatus
  const [quiz, setQuiz] = useState<{
    QuizId: number;
    Question: string;
    Targets: { id: number; type: "text" | "image"; value: string }[];
    Options: { id: number; type: "text" | "image"; value: string }[];
    CorrectPairs: { targetId: number; optionId: number }[];
  } | null>(null);

  const [assignments, setAssignments] = useState<{
    [key: number]: number | null;
  }>({});
  const [activeTarget, setActiveTarget] = useState<number | null>(null);
  const [feedback, setFeedback] = useState("");

  const targetCount = quiz?.Targets?.length || 0;
  const { width } = useOrientation();
  const isWide = width >= 768;
  const [showSolutions, setShowSolutions] = useState(false);
  const [correctCount, setCorrectCount] = useState(0);

  // --- Quiz laden ---
  useEffect(() => {
    const data = demoQuizAssign.find((q) => q.QuizId === quizId) ?? null;
    if (!data) return;

    setQuiz(data);
    console.log(
      "Targets:",
      data.Targets.map((t: any) => t.value),
    );
    console.log("Verfügbare Keys in imageMap:", Object.keys(imageMap));

    const init: { [key: number]: number | null } = {};
    data.Targets.forEach((t) => (init[t.id] = null));
    setAssignments(init);

    setActiveTarget(null);
    setFeedback("");
    onSelect(null);
  }, [quizId]);

  useEffect(() => {
    if (externalShowSolutions) {
      setShowSolutions(true);
    }
  }, [externalShowSolutions]);

  // --- Auswertung bei Bestätigung ---
  useEffect(() => {
    if (confirmRequested && quiz) {
      let correctCount = 0;
      quiz.CorrectPairs.forEach((p: any) => {
        if (Number(assignments[p.targetId]) === Number(p.optionId))
          correctCount++;
      });

      const total = quiz.CorrectPairs.length;
      const isAllCorrect = correctCount === total;
      const isPartial = correctCount > 0 && correctCount < total;

      let message = "";
      if (isAllCorrect) message = "Gut gemacht!";
      else if (isPartial) message = "Fast richtig!";
      else message = "Leider falsch.";

      setFeedback(message);
      onFeedback(message);
      setCorrectCount(correctCount);
      setShowSolutions(false); // Reset bei neuem Versuch
      onResult(correctCount, total);
      onConfirmed();
    }
  }, [confirmRequested]);

  // --- Ziel (Bild/Text oben) auswählen ---
  const handleTargetSelect = (id: number) => {
    if (feedback) return;
    setActiveTarget(id);
  };

  // --- Option (Antwort unten) wählen ---
  const handleOptionSelect = (optionId: number) => {
    if (activeTarget === null) return;
    const updated = { ...assignments, [activeTarget]: optionId };
    setAssignments(updated);

    // 👇 zuerst prüfen und an Parent senden
    const allFilled = Object.values(updated).every((v) => v !== null);
    onSelect(allFilled ? "ready" : null);

    // 👇 erst DANACH Target zurücksetzen
    setActiveTarget(null);
  };

  useEffect(() => {
    if (
      feedback &&
      correctCount < (quiz?.CorrectPairs?.length || 0) &&
      !showSolutions
    ) {
      setUndoElement(
        <TouchableOpacity
          onPress={() => setShowSolutions(true)}
          style={{
            paddingVertical: 8,
            paddingHorizontal: 18,
            borderWidth: 1.5,
            borderRadius: 10,
            borderColor: theme.colors.primary,
            backgroundColor: "transparent",
          }}
        >
          <Text
            style={{
              color: theme.colors.primary,
              fontFamily: "Lato-Bold",
              fontSize: scaleFont(16),
              textAlign: "center",
            }}
          >
            Lösung
          </Text>
        </TouchableOpacity>,
      );
    } else {
      const isActive =
        Object.values(assignments).some((v) => v !== null) && !feedback;

      setUndoElement(
        <TouchableOpacity
          onPress={handleUndo}
          disabled={!isActive}
          style={styles.undoButton}
        >
          <Text
            style={[
              styles.undoIcon,
              { color: isActive ? theme.colors.primary : "#a0a0a0" },
            ]}
          >
            ⌫
          </Text>
        </TouchableOpacity>,
      );
    }
  }, [assignments, feedback, showSolutions]);

  useEffect(() => {
    if (selected === "undo") {
      handleUndo();
      onSelect(null); // Signal zurücksetzen
    }
  }, [selected]);

  // --- Zuordnung löschen ---
  const handleUndo = () => {
    // Wenn gar keine Zuordnung vorhanden → nichts tun
    const hasAssignments = Object.values(assignments).some((v) => v !== null);
    if (!hasAssignments) return;

    // Wenn ein Target aktiv ist → nur dieses löschen
    if (activeTarget !== null) {
      const updated = { ...assignments, [activeTarget]: null };
      setAssignments(updated);
      const allFilled = Object.values(updated).every((v) => v !== null);
      onSelect(allFilled ? "ready" : null);
      setActiveTarget(null);
      return;
    }

    // Sonst: letztes befülltes Target zurücksetzen
    const lastKey = Object.keys(assignments)
      .reverse()
      .map(Number)
      .find((k) => assignments[k] !== null);
    if (lastKey !== undefined) {
      const updated = { ...assignments, [lastKey]: null };
      setAssignments(updated);
      const allFilled = Object.values(updated).every((v) => v !== null);
      onSelect(allFilled ? "ready" : null);
    }
  };

  if (!quiz) return null;

  return (
    <ScrollView
      contentContainerStyle={[
        styles.container,
        {
          backgroundColor: theme.colors.background,
          flexGrow: 1,
          paddingTop: isWide ? dynamicSpacing(20, 30) : dynamicSpacing(20, 30),
          paddingBottom: isWide
            ? dynamicSpacing(20, 30) // vorher 40,60
            : dynamicSpacing(20, 30), // vorher 80,100
        },
      ]}
      showsVerticalScrollIndicator={false}
    >
      {/* Frage */}
      <Text style={[styles.question, { color: theme.colors.text }]}>
        {quiz.Question}
      </Text>

      {/* Targets oben */}
      <View
        style={[styles.targetsList, { width: "90%", alignItems: "center" }]}
      >
        {quiz.Targets.map((t: any) => (
          <TouchableOpacity
            key={t.id}
            style={[
              styles.targetBox,
              (() => {
                let bgColor = isDarkMode ? "#1f2b37" : theme.colors.card;
                let borderColor = theme.colors.border;
                let borderWidth = 1.5;

                if (!feedback && activeTarget === t.id) {
                  if (isDarkMode) {
                    bgColor = theme.colors.card;
                    borderColor = "#d1d1d1";
                    borderWidth = 2;
                  } else {
                    bgColor = "#d1d1d1";
                    borderColor = "#a0a0a0";
                    borderWidth = 2;
                  }
                } else if (feedback) {
                  const correctPair = quiz.CorrectPairs.find(
                    (p: any) => p.targetId === t.id,
                  );
                  const assigned = assignments[t.id];
                  const isCorrect = assigned === correctPair?.optionId;

                  if (isCorrect) {
                    bgColor = "#4CAF5020";
                    borderColor = "#4CAF50";
                  } else if (assigned !== null) {
                    if (showSolutions) {
                      bgColor = theme.colors.card;
                      borderColor = "#a0a0a0";
                    } else {
                      bgColor = "#E5393520";
                      borderColor = "#E53935";
                    }
                  }
                }

                return { backgroundColor: bgColor, borderColor, borderWidth };
              })(),
            ]}
            onPress={() => handleTargetSelect(t.id)}
            disabled={!!feedback}
          >
            {t.type === "image" ? (
              (() => {
                console.log(
                  "Bild gesucht:",
                  t.value,
                  "→",
                  !!getImageByKey(t.value),
                );
                return (
                  <View style={styles.targetImageWrapper}>
                    <Image
                      source={getImageByKey(t.value)}
                      style={{
                        width: "100%",
                        height: "100%",
                      }}
                      resizeMode="contain"
                    />
                  </View>
                );
              })()
            ) : (
              <Text style={[styles.targetText, { color: theme.colors.text }]}>
                {t.value}
              </Text>
            )}

            {(() => {
              const assignedId = assignments[t.id];
              if (!assignedId) return null;

              const assignedText = quiz.Options.find(
                (o: any) => o.id === assignedId,
              )?.value;
              const isAfterConfirm = !!feedback;

              let displayText = assignedText;
              let displayColor = isAfterConfirm
                ? theme.colors.text
                : theme.colors.primary;

              if (showSolutions) {
                const correctPair = quiz.CorrectPairs.find(
                  (p: any) => p.targetId === t.id,
                );
                const correctId = correctPair?.optionId;
                const isCorrect = assignedId === correctId;

                if (!isCorrect) {
                  const correctText = quiz.Options.find(
                    (o: any) => o.id === correctId,
                  )?.value;
                  displayText = correctText;
                  displayColor = "#666";
                } else {
                  displayColor = "#4CAF50";
                }
              }

              return (
                <View
                  style={[
                    styles.assignedLabel,
                    {
                      alignItems: "center",
                      justifyContent: "center",
                      backgroundColor: theme.colors.card,
                      borderColor: "#d1d1d1",
                    },
                  ]}
                >
                  <Text
                    style={[
                      styles.assignedLabelText,
                      {
                        color: displayColor,
                        fontFamily: "Lato-Bold",
                        textAlign: "center",
                      },
                    ]}
                  >
                    {displayText}
                  </Text>
                </View>
              );
            })()}
          </TouchableOpacity>
        ))}
      </View>

      {/* Antwortoptionen unten */}
      <View
        style={{
          width: isWide ? "70%" : "90%",
          flexDirection: "column",
          alignItems: "center",
          gap: dynamicSpacing(14, 18),
          marginTop: isWide ? dynamicSpacing(10, 20) : 0,
        }}
      >
        {quiz.Options.map((opt: any) => (
          <TouchableOpacity
            key={opt.id}
            style={[
              styles.optionButton,
              {
                backgroundColor: theme.colors.card,
                borderColor: "#d1d1d1",
                opacity: Object.values(assignments).includes(opt.id) ? 0.5 : 1,
              },
            ]}
            onPress={() => handleOptionSelect(opt.id)}
            disabled={!!feedback || Object.values(assignments).includes(opt.id)}
          >
            {opt.type === "image" ? (
              <Image
                source={getImageByKey(opt.value)}
                style={styles.optionImage}
                resizeMode="contain"
              />
            ) : (
              <Text style={[styles.optionText, { color: theme.colors.text }]}>
                {hyphenateLabel(String(opt.value ?? ""))}
              </Text>
            )}
          </TouchableOpacity>
        ))}
      </View>
    </ScrollView>
  );
}

