import { createStackNavigator } from "@react-navigation/stack";
import ExamResultScreen from "../Exam/ExamresultScreen";
import ExamScreen from "../Exam/ExamScreen";
import ExamStartScreen from "../Exam/ExamStartScreen";

const Stack = createStackNavigator();

export default function ExamNavigator() {
  return (
    <Stack.Navigator>
      <Stack.Screen
        name="ExamScreen"
        component={ExamScreen}
        options={{ headerShown: true, title: "Start" }}
      />
      <Stack.Screen
        name="ExamStart"
        component={ExamStartScreen}
        options={{ title: "Einleitung" }}
      />
      <Stack.Screen name="ExamResult" component={ExamResultScreen} />
    </Stack.Navigator>
  );
}
