// app/Settings/SettingsScreen.tsx

import { useTheme } from "@/app/context/ThemeContext";
import { getContentMaxWidth, useOrientation } from "@/app/utils/responsive";
import { Ionicons } from "@expo/vector-icons";
import AsyncStorage from "@react-native-async-storage/async-storage";
import { NavigationProp, useNavigation } from "@react-navigation/native";
import * as React from "react";
import { useEffect, useLayoutEffect, useState } from "react";

import {
  Image,
  ScrollView,
  StyleSheet,
  Switch,
  Text,
  TextInput,
  TouchableOpacity,
  View,
} from "react-native";
import { SafeAreaView } from "react-native-safe-area-context";
import { RootTabParamList } from "../types/navigationTypes";
import { dynamicSpacing, isTablet, scaleFont } from "../utils/responsive";

export default function SettingsScreen(): React.JSX.Element {
  const navigation = useNavigation<NavigationProp<RootTabParamList>>();
  const { theme, toggleTheme, mode } = useTheme(); // ← Context
  const themeColors = theme.colors;
  const { width } = useOrientation();
  const isWide = width >= 768;
  const contentMaxWidth = getContentMaxWidth(isTablet ? 700 : 520);
  const isDemo = true;

  const [name, setName] = useState<string>("");
  const [isEditing, setIsEditing] = useState<boolean>(false);

  useLayoutEffect(() => {
    navigation.setOptions({
      headerTitle: "Einstellungen",
      headerStyle: { backgroundColor: themeColors.background },
      headerTitleStyle: {
        fontFamily: "Montserrat-Bold",
        fontSize: scaleFont(18),
        color: themeColors.text,
      },
    });
  }, [navigation, themeColors]);

  useEffect(() => {
    const loadName = async (): Promise<void> => {
      const saved = await AsyncStorage.getItem("userName");
      if (saved) setName(saved);
    };
    void loadName();
  }, []);

  const handleSave = async (): Promise<void> => {
    await AsyncStorage.setItem("userName", name);
    setIsEditing(false);
  };

  return (
    <SafeAreaView style={{ flex: 1, backgroundColor: themeColors.background }}>
      <View style={{ flex: 1 }}>
        <View
          style={[styles.lockBanner, { backgroundColor: themeColors.card }]}
        >
          <Ionicons name="lock-closed" size={16} color={themeColors.text} />
          <Text style={[styles.lockBannerText, { color: themeColors.text }]}>
            Alle Funktionen in der Vollversion verfügbar
          </Text>
        </View>
        <ScrollView
          style={{ flex: 1 }}
          contentContainerStyle={[
            styles.container,
            isWide && {
              alignItems: "center",
              paddingHorizontal: dynamicSpacing(30, 40),
              backgroundColor: themeColors.background,
            },
          ]}
          showsVerticalScrollIndicator={false}
        >
          <View
            style={[
              isWide && {
                backgroundColor: themeColors.background,
                borderRadius: 16,
                paddingTop: dynamicSpacing(30, 40),
                paddingHorizontal: dynamicSpacing(30, 40),
                maxWidth: contentMaxWidth,
                width: "100%",
                alignSelf: "center",
              },
            ]}
          >
            {/* Header-Bereich */}
            <View
              style={[
                styles.headerContainer,
                { backgroundColor: themeColors.background },
              ]}
            />
            {/* Name bearbeiten */}
            <View style={styles.section}>
              <View style={styles.row}>
                {isEditing ? (
                  <TextInput
                    style={[
                      styles.input,
                      {
                        backgroundColor: isDemo ? "#d1d1d1" : themeColors.card,
                        color: isDemo ? "#5f5f5f" : themeColors.text,
                        borderColor: isDemo ? "#a0a0a0" : themeColors.border,
                      },
                    ]}
                    value={name}
                    onChangeText={setName}
                    placeholder="Namen festlegen"
                    placeholderTextColor="#aaa"
                    editable={!isDemo}
                  />
                ) : (
                  <Text style={[styles.name, { color: themeColors.text }]}>
                    {name || "Wie heißt du?"}
                  </Text>
                )}

                <TouchableOpacity
                  style={[
                    styles.button,
                    isEditing ? styles.saveButton : styles.editButton,
                    isDemo && styles.disabledButton,
                  ]}
                  onPress={isEditing ? handleSave : () => setIsEditing(true)}
                  disabled={isDemo}
                >
                  <Text
                    style={[
                      styles.buttonText,
                      isDemo && styles.disabledButtonText,
                    ]}
                  >
                    {isEditing ? "Speichern" : "Ändern"}
                  </Text>
                </TouchableOpacity>
              </View>
            </View>
            <View
              style={[styles.divider, { backgroundColor: themeColors.border }]}
            />
            {/* Dark Mode */}
            <View style={styles.section}>
              <View style={[styles.row, isDemo && styles.disabledRow]}>
                <Text
                  style={[
                    styles.label,
                    { color: isDemo ? "#5f5f5f" : themeColors.text },
                  ]}
                >
                  Dark Mode
                </Text>
                <Switch
                  value={mode === "dark"}
                  onValueChange={toggleTheme}
                  disabled={isDemo}
                  trackColor={{ false: "#a0a0a0", true: "#a0a0a0" }}
                  thumbColor={"#d1d1d1"}
                />
              </View>
            </View>

            <View
              style={[styles.divider, { backgroundColor: themeColors.border }]}
            />
            {/* Navigation Links */}
            {[
              { label: "Datenschutzerklärung", screen: "PrivacyPolicyScreen" },
              { label: "Nutzungsbedingungen", screen: "TermsOfServiceScreen" },
              { label: "Updates", screen: "UpdatesInfoScreen" },
              { label: "Impressum", screen: "ImpressumScreen" },
            ].map((item, index) => (
              <React.Fragment key={item.screen}>
                <TouchableOpacity
                  style={styles.section}
                  onPress={() =>
                    navigation.navigate(item.screen as keyof RootTabParamList)
                  }
                >
                  <Text style={[styles.label, { color: themeColors.text }]}>
                    {item.label}
                  </Text>
                </TouchableOpacity>
                {index < 3 && (
                  <View
                    style={[
                      styles.divider,
                      { backgroundColor: themeColors.border },
                    ]}
                  />
                )}
              </React.Fragment>
            ))}
          </View>
        </ScrollView>
      </View>

      {/* Footer */}
      <View style={styles.footer}>
        <Image
          source={
            mode === "dark"
              ? require("../../assets/images/splash-icon.png")
              : require("../../assets/images/skilt_GP1_logo.png")
          }
          style={{
            width: isTablet ? 40 : 32,
            height: isTablet ? 40 : 32,
            marginRight: isTablet ? 12 : 8,
          }}
          resizeMode="contain"
        />
        <Text style={[styles.versionText, { color: themeColors.text }]}>
          Version: 1.0.1
        </Text>
      </View>
    </SafeAreaView>
  );
}

const styles = StyleSheet.create({
  container: {
    paddingHorizontal: dynamicSpacing(20, 40),
    paddingVertical: dynamicSpacing(24, 30),
  },
  headerContainer: {
    paddingVertical: 0,
    alignItems: "center",
    marginBottom: dynamicSpacing(10, 14),
  },
  section: {
    paddingVertical: dynamicSpacing(22, 28),
    paddingHorizontal: dynamicSpacing(22, 28),
    backgroundColor: "transparent",
    marginBottom: 0,
  },
  row: {
    flexDirection: "row",
    alignItems: "center",
    justifyContent: "space-between",
  },
  name: {
    fontFamily: "Montserrat-Regular",
    fontSize: scaleFont(18),
  },
  input: {
    fontFamily: "Montserrat-Regular",
    fontSize: scaleFont(18),
    paddingVertical: dynamicSpacing(6, 10),
    paddingHorizontal: dynamicSpacing(10, 16),
    borderWidth: 1,
    borderRadius: 8,
    flex: 1,
  },
  button: {
    paddingVertical: dynamicSpacing(14, 18),
    paddingHorizontal: dynamicSpacing(14, 18),
    borderRadius: 8,
    marginTop: dynamicSpacing(6, 10),
    marginLeft: 10,
    elevation: 0, // ← Schatten auf Android aus
    shadowColor: "transparent", // ← Schatten auf iOS aus
  },
  editButton: {
    backgroundColor: "#007BFF",
  },
  saveButton: {
    backgroundColor: "#FFA500",
  },
  buttonText: {
    color: "#fff",
    fontFamily: "Montserrat-Bold",
    fontSize: scaleFont(14),
  },
  divider: {
    height: 1,
    backgroundColor: "#ccc",
    marginHorizontal: dynamicSpacing(20, 24),
  },
  label: {
    fontFamily: "Montserrat-SemiBold",
    fontSize: scaleFont(18),
  },
  footer: {
    height: 80,
    flexDirection: "row",
    justifyContent: "space-between",
    alignItems: "center",
    paddingHorizontal: dynamicSpacing(20, 40),
  },
  versionText: {
    fontFamily: "Montserrat-Regular",
    fontSize: scaleFont(16),
  },
  // Styles ergänzen (unten in StyleSheet)

  lockBannerText: {
    fontFamily: "Montserrat-Regular",
    fontSize: scaleFont(12),
  },

  disabledRow: {
    backgroundColor: "#d1d1d1",
    borderRadius: 12,
    borderWidth: 1,
    borderColor: "#a0a0a0",
    paddingVertical: dynamicSpacing(12, 16),
    paddingHorizontal: dynamicSpacing(14, 18),
  },
  lockBanner: {
    flexDirection: "row",
    alignItems: "center",
    gap: 8,
    borderRadius: 12,
    paddingVertical: 10,
    paddingHorizontal: 12,
    borderWidth: 1,
    opacity: 0.75,
    marginBottom: dynamicSpacing(14, 18),
  },

  disabledButton: {
    backgroundColor: "#d1d1d1",
    borderColor: "#a0a0a0",
    borderWidth: 1,
  },
  disabledButtonText: {
    color: "#5f5f5f",
  },
});
