// HomeScreen.tsx

import { useTheme } from "@/app/context/ThemeContext";
import { Colors } from "@/constants/theme";
import { Ionicons, MaterialCommunityIcons } from "@expo/vector-icons";
import AsyncStorage from "@react-native-async-storage/async-storage";
import { useNavigation } from "@react-navigation/native";
import { useEffect, useLayoutEffect, useRef, useState } from "react";

import {
  AppState,
  Image,
  ScrollView,
  StyleSheet,
  Text,
  TouchableOpacity,
  View,
} from "react-native";
import {
  dynamicIconSize,
  dynamicSpacing,
  getContentMaxWidth,
  isTablet,
  scaleFont,
  useOrientation,
} from "../utils/responsive";

export default function HomeScreen() {
  const navigation = useNavigation<any>();
  const { mode } = useTheme();
  const themeColors = Colors[mode];
  const { width } = useOrientation();
  const contentMaxWidth = getContentMaxWidth(isTablet ? 700 : 520);
  const isWide = width >= 768;
  const pageBg = themeColors.background;

  const contentBg = themeColors.background;

  const [username, setUsername] = useState<string>(""); // NEU

  const [hasSetGoal, setHasSetGoal] = useState(false);
  const [activeDays, setActiveDays] = useState<string[]>([]);
  const [goalDays, setGoalDays] = useState(0);
  const [loading, setLoading] = useState(true);
  const appState = useRef(AppState.currentState);
  const startTime = useRef<number | null>(null);

  // Misst, wie lange die App aktiv war, und speichert den Tag,wenn sie mindestens 5 Minuten geöffnet war
  useEffect(() => {
    const subscription = AppState.addEventListener(
      "change",
      async (nextAppState) => {
        if (
          appState.current.match(/inactive|background/) &&
          nextAppState === "active"
        ) {
          startTime.current = Date.now(); // App geöffnet
        } else if (
          appState.current === "active" &&
          nextAppState.match(/inactive|background/)
        ) {
          if (startTime.current) {
            const minutes = (Date.now() - startTime.current) / 60000;
            if (minutes >= 5) {
              const key = new Date().toDateString();
              await AsyncStorage.setItem(key, String(minutes));
            }
          }
        }
        appState.current = nextAppState;
      },
    );

    return () => subscription.remove();
  }, []);

  useLayoutEffect(() => {
    navigation.setOptions({
      headerTitle: "Start",
      headerStyle: { backgroundColor: themeColors.background },
      headerTitleStyle: {
        fontFamily: "Montserrat-Bold",
        fontSize: scaleFont(18),
        color: themeColors.text,
      },
    });
  }, [navigation, themeColors.background, themeColors.text]);

  // Lädt gespeicherte Streak-Daten (Ziel, aktive Tage, Fortschritt) aus AsyncStorage und aktualisiert den aktuellen Wochenstatus beim ersten App-Start

  useEffect(() => {
    (async () => {
      const savedGoal = await AsyncStorage.getItem("hasSetGoal");
      setHasSetGoal(savedGoal === "true");

      // aktive Tage prüfen
      const dailyGoal =
        Number(await AsyncStorage.getItem("dailyMinutes")) || 10;
      const goal = Number(await AsyncStorage.getItem("goalDays")) || 0;
      setGoalDays(goal);

      const temp: string[] = [];
      for (let i = 0; i < 7; i++) {
        const date = new Date();
        date.setDate(date.getDate() - (6 - i)); // letzte 7 Tage
        const key = date.toDateString();
        const minutes = Number(await AsyncStorage.getItem(key)) || 0;
        if (minutes >= dailyGoal) temp.push(key);
      }
      setActiveDays(temp);

      // 👇 NEU: Name laden
      const storedName = await AsyncStorage.getItem("userName");
      if (storedName) setUsername(storedName);

      setLoading(false);
    })();
  }, []);

  if (loading) return null;

  return (
    <View style={[styles.screen, { backgroundColor: pageBg }]}>
      <ScrollView
        style={{ flex: 1 }}
        contentContainerStyle={[
          styles.scrollContent,
          isWide && { paddingHorizontal: dynamicSpacing(30, 40) },
        ]}
        showsVerticalScrollIndicator={false}
      >
        <View
          style={[
            styles.contentWrapper,
            { backgroundColor: contentBg },
            isWide && {
              width: "100%",
              maxWidth: contentMaxWidth,
              borderRadius: 16,
            },
          ]}
        >
          <View style={styles.headerWrap}>
            <Image
              source={require("@/assets/images/skilt_GP1_logo.png")}
              style={styles.headerLogo}
              resizeMode="contain"
            />
            <View>
              <Text style={[styles.headerTitle, { color: themeColors.text }]}>
                SHK GP1
              </Text>
              <Text
                style={[styles.headerSubtitle, { color: themeColors.text }]}
              >
                Prüfungsvorbereitung Teil 1
              </Text>
            </View>
          </View>

          {/* Lern-Streak Bereich */}
          {!hasSetGoal ? (
            // 1. Wenn noch kein Ziel gesetzt ist
            <TouchableOpacity
              style={[
                styles.streakButton,
                {
                  backgroundColor: themeColors.card,
                  borderColor: themeColors.border,
                },
              ]}
              onPress={() => navigation.navigate("Streak")}
            >
              <View style={styles.streakTextWrap}>
                <Text style={[styles.streakTitle, { color: themeColors.text }]}>
                  Lern-Streak
                </Text>
                <Text
                  style={[styles.streakSubtitle, { color: themeColors.text }]}
                >
                  Setze dein Wochenziel
                </Text>
              </View>
              <MaterialCommunityIcons
                name="fire"
                size={dynamicIconSize(50, 58)}
                color={themeColors.tint}
              />
            </TouchableOpacity>
          ) : (
            // 2. Wenn Ziel gesetzt wurde
            <View
              style={[
                styles.streakButton,
                {
                  backgroundColor: "transparent",
                  borderWidth: 0.7,
                  borderColor: "#d6d6d6",
                  shadowOpacity: 0,
                  elevation: 0,
                  paddingVertical: dynamicSpacing(10, 16),
                },
              ]}
            >
              <View style={styles.streakTextWrap}>
                <Text style={[styles.streakTitle, { color: themeColors.text }]}>
                  Lern-Streak
                </Text>

                {/* Wochencontainer */}
                <View
                  style={[
                    styles.weekContainer,
                    { borderColor: themeColors.border },
                  ]}
                >
                  {(() => {
                    const today = new Date();
                    const dayOfWeek = today.getDay() === 0 ? 7 : today.getDay(); // So=7
                    const monday = new Date(today);
                    monday.setDate(today.getDate() - (dayOfWeek - 1));

                    return ["M", "D", "M", "D", "F", "S", "S"].map(
                      (day, index) => {
                        const date = new Date(monday);
                        date.setDate(monday.getDate() + index);

                        const key = date.toDateString();
                        const isToday = key === today.toDateString();
                        const isActive = activeDays.includes(key);
                        const extraDays = activeDays.length > goalDays;

                        return (
                          <View key={index} style={styles.dayContainer}>
                            <Text
                              style={[
                                styles.dayText,
                                { color: themeColors.text },
                              ]}
                            >
                              {day}
                            </Text>

                            <View
                              style={[
                                styles.dayBox,
                                {
                                  borderColor: isToday
                                    ? "#FFA500"
                                    : themeColors.border,
                                  backgroundColor: isToday
                                    ? themeColors.card
                                    : "transparent",
                                },
                              ]}
                            >
                              {isActive &&
                                (extraDays ? (
                                  <Ionicons
                                    name="flame"
                                    size={18}
                                    color="#FFA500"
                                  />
                                ) : (
                                  <Ionicons
                                    name="checkmark-circle"
                                    size={18}
                                    color="#5fd36d"
                                  />
                                ))}
                            </View>
                          </View>
                        );
                      },
                    );
                  })()}
                </View>

                {/* Link zu Streak-Einstellungen */}
                <TouchableOpacity onPress={() => {}}>
                  <Text
                    style={[
                      styles.streakSubtitle,
                      { color: themeColors.tint, marginTop: 8 },
                    ]}
                  >
                    Streak-Einstellungen ändern →
                  </Text>
                </TouchableOpacity>
              </View>
            </View>
          )}

          {/* Trainings Button */}
          <View
            style={[
              styles.trainingCard,
              {
                backgroundColor: themeColors.card,
                borderColor: themeColors.border,
              },
            ]}
          >
            <Text style={[styles.trainingTitle, { color: themeColors.text }]}>
              Training
            </Text>
            <Text
              style={[styles.trainingSubtitle, { color: themeColors.text }]}
            >
              Wiederhole Grundlagen und löse Aufgaben Schritt für Schritt.
            </Text>

            <TouchableOpacity
              style={[
                styles.startButton,
                { backgroundColor: themeColors.buttonBackground },
              ]}
              onPress={() => navigation.navigate("Training")}
            >
              <Text style={styles.startButtonText}>Los geht’s</Text>
            </TouchableOpacity>
          </View>
          {/* Exam Modul */}
          <View
            style={[
              styles.testSection,
              {
                width: isWide ? "70%" : isTablet ? "80%" : "85%",

                paddingVertical: dynamicSpacing(14, 18),
                paddingHorizontal: dynamicSpacing(18, 26),
                borderWidth: 1,
                borderColor: themeColors.border,
                borderRadius: isTablet ? 18 : 12,
                marginTop: isWide
                  ? dynamicSpacing(16, 20)
                  : dynamicSpacing(30, 35),
                marginBottom: isWide
                  ? dynamicSpacing(18, 24)
                  : dynamicSpacing(25, 35),
              },
            ]}
          >
            {/* Obere Zeile: Text links, Uhr rechts */}
            <View style={{ flexDirection: "row", alignItems: "center" }}>
              <View style={{ flex: 1 }}>
                <Text
                  style={[
                    styles.testTitle,
                    {
                      color: themeColors.text,
                      fontSize: isWide ? scaleFont(22) : scaleFont(20),
                    },
                  ]}
                >
                  Prüfung
                </Text>
                <Text
                  style={[
                    styles.testSubDescription,
                    { color: themeColors.text },
                  ]}
                >
                  Teste deinen Wissenstand
                </Text>
              </View>
            </View>

            {/* Button unten links */}
            <TouchableOpacity
              style={[
                styles.testButton,
                {
                  alignSelf: "stretch",
                  marginTop: 14,
                  justifyContent: "space-between",
                  paddingLeft: dynamicSpacing(8, 12),
                  paddingRight: dynamicSpacing(18, 26),
                },
              ]}
              onPress={() => navigation.navigate("Exam")}
            >
              <MaterialCommunityIcons
                name="progress-clock"
                size={scaleFont(36)}
                color={themeColors.icon}
              />

              <View style={{ flexDirection: "row", alignItems: "center" }}>
                <Text
                  style={[
                    styles.testButtonText,
                    { color: themeColors.buttonBackground },
                  ]}
                >
                  Starten
                </Text>
                <Ionicons
                  name="arrow-forward-outline"
                  size={scaleFont(18)}
                  color={themeColors.buttonBackground}
                />
              </View>
            </TouchableOpacity>
          </View>
        </View>
      </ScrollView>
    </View>
  );
}

