// app/screens/Training/ChaptersScreen.tsx

import { useTheme } from "@/app/context/ThemeContext";
import { useNavigation } from "@react-navigation/native";
import { useEffect, useState } from "react";
import {
  Image,
  ScrollView,
  StyleSheet,
  Text,
  TouchableOpacity,
  View,
} from "react-native";
import { SafeAreaView } from "react-native-safe-area-context";
import { demoChapters } from "../data/demoChapters";
import { getImageByKey } from "../utils/imageMappings";
import {
  dynamicIconSize,
  dynamicSpacing,
  getContentMaxWidth,
  isTablet,
  scaleFont,
  useOrientation,
} from "../utils/responsive";

export default function ChaptersScreen() {
  const navigation = useNavigation<any>();
  const { width } = useOrientation();
  const isWide = width >= 768;
  const contentMaxWidth = getContentMaxWidth(520);

  const { theme } = useTheme();
  if (!theme?.colors) return null;

  const [chapters, setChapters] = useState<
    {
      ChapterId: number;
      ChapterName: string;
      ChapterIntro: string;
      Year: number;
      ImageMarker: string;
    }[]
  >([]);

  useEffect(() => {
    setChapters(demoChapters);
  }, []);

  const handlePress = (chapterId: number, name: string) => {
    navigation.navigate("Subchapters", {
      chapterId,
      chapterTitle: name,
    });
  };

  return (
    <SafeAreaView style={{ flex: 1, backgroundColor: theme.colors.background }}>
      <ScrollView
        style={{ flex: 1, width: "100%" }}
        contentContainerStyle={[styles.scrollContent, { alignItems: "center" }]}
        showsVerticalScrollIndicator={false}
      >
        <View
          style={[
            {
              width: "100%",
              alignItems: "center",
            },
            isWide && {
              maxWidth: contentMaxWidth,
            },
          ]}
        >
          <Text style={[styles.header, { color: theme.colors.text }]}>
            Themenübersicht
          </Text>

          {chapters.map((ch) => (
            <TouchableOpacity
              key={ch.ChapterId}
              style={[
                styles.card,
                {
                  backgroundColor: theme.colors.card,
                  borderColor: theme.colors.border,
                  width: "90%",
                },
              ]}
              onPress={() => handlePress(ch.ChapterId, ch.ChapterName)}
            >
              <View style={styles.textContainer}>
                <Text style={[styles.title, { color: theme.colors.text }]}>
                  {ch.ChapterName}
                </Text>
                <Text style={[styles.intro, { color: theme.colors.text }]}>
                  {ch.ChapterIntro}
                </Text>
              </View>
              <Image
                source={getImageByKey(ch.ImageMarker)}
                style={styles.image}
                resizeMode="contain"
              />
            </TouchableOpacity>
          ))}
        </View>
      </ScrollView>
    </SafeAreaView>
  );
}

const styles = StyleSheet.create({
  scrollContent: {
    alignItems: "center",
    paddingVertical: dynamicSpacing(10, 14),
  },

  contentWrapper: {
    width: "100%",
    alignItems: "center",
  },

  header: {
    fontSize: scaleFont(24),
    fontFamily: "Lato-Bold",
    marginBottom: dynamicSpacing(20, 26),
    textAlign: "center",
  },
  card: {
    flexDirection: "row",
    alignItems: "center",
    borderWidth: 1,
    borderRadius: isTablet ? 18 : 12,
    paddingVertical: dynamicSpacing(16, 22),
    paddingHorizontal: dynamicSpacing(14, 20),
    marginBottom: dynamicSpacing(16, 24),
    shadowColor: "#000",
    shadowOffset: { width: 0, height: 2 },
    shadowOpacity: 0.1,
    shadowRadius: 3,
    elevation: 2,
  },
  textContainer: {
    flex: 2,
  },
  title: {
    fontSize: scaleFont(20),
    fontFamily: "Lato-Bold",
    marginBottom: dynamicSpacing(6, 8),
  },
  intro: {
    fontSize: scaleFont(15),
    fontFamily: "OpenSans-Regular",
  },
  image: {
    width: dynamicIconSize(70, 100),
    height: dynamicIconSize(70, 100),
    borderRadius: 8,
    marginLeft: dynamicSpacing(12, 18),
  },
});
