// app/screens/Training/QuizExplanationSlide.tsx

import { useTheme } from "@/app/context/ThemeContext";
import { demoQuizExplanation } from "@/app/data/demoQuizExplanation";
import { hyphenateLabel } from "@/app/utils/hyphenateLabel";
import {
  dynamicSpacing,
  isTablet,
  scaleFont,
  useOrientation,
} from "@/app/utils/responsive";

import { useEffect, useState } from "react";
import {
  ScrollView,
  StyleSheet,
  Text,
  TouchableOpacity,
  View,
} from "react-native";

interface QuizExplanationSlideProps {
  quizId: number;
  selected: string | null;
  onSelect: (v: string) => void;
  confirmRequested: boolean;
  onConfirmed: () => void;
  onResult: (correctCount: number, totalCount: number) => void;
  onFeedback: (text: string) => void;
}

export default function QuizExplanationSlide({
  quizId,
  selected,
  onSelect,
  confirmRequested,
  onConfirmed,
  onResult,
  onFeedback,
}: QuizExplanationSlideProps) {
  const { theme } = useTheme();
  const { width } = useOrientation();
  const isWide = width >= 768;

  const isDarkMode = theme.dark === true;
  const [quiz, setQuiz] = useState<{
    Question: string;
    OptionA: string;
    OptionB: string;
    OptionC: string;
    CorrectOption: "A" | "B" | "C";
  } | null>(null);

  const [feedback, setFeedback] = useState<string>("");

  // Quizdaten laden
  useEffect(() => {
    const loadQuiz = async () => {
      const data = demoQuizExplanation.find((q) => q.QuizId === quizId) ?? null;
      setFeedback("");
      setQuiz(data);
    };
    loadQuiz();
  }, [quizId]);

  // Feedback erst zeigen, wenn Bestätigen gedrückt wurde
  useEffect(() => {
    if (confirmRequested && selected && quiz) {
      const isCorrect = selected === quiz.CorrectOption;
      const message = isCorrect ? "Gut gemacht!" : "Leider falsch.";
      setFeedback(message);
      onFeedback(message);
      onResult(isCorrect ? 1 : 0, 1);
      onConfirmed();
    }
  }, [confirmRequested]);

  if (!quiz) return null;

  return (
    <ScrollView
      contentContainerStyle={[
        styles.container,
        {
          backgroundColor: theme.colors.background,
          flexGrow: 1,
          paddingTop: isWide ? dynamicSpacing(20, 30) : dynamicSpacing(60, 50),
          paddingBottom: isWide
            ? dynamicSpacing(40, 60)
            : dynamicSpacing(50, 70),
        },
      ]}
      showsVerticalScrollIndicator={false}
    >
      <Text
        style={[
          styles.question,
          {
            color: theme.colors.text,
            marginBottom: isWide
              ? dynamicSpacing(20, 30)
              : dynamicSpacing(40, 50),
          },
        ]}
      >
        {quiz.Question}
      </Text>

      <View style={styles.optionsContainer}>
        {["A", "B", "C"].map((key) => (
          <TouchableOpacity
            key={key}
            style={[
              styles.optionButton,
              (() => {
                let bgColor = theme.colors.card;
                let borderColor = theme.colors.border;
                let borderWidth = 1.5;

                if (selected === key && !feedback) {
                  if (isDarkMode) {
                    // Darkmode wie bisher
                    bgColor = theme.colors.card;
                    borderColor = "#d1d1d1";
                    borderWidth = 2;
                  } else {
                    // Lightmode: deutlich graue Markierung
                    bgColor = "#d1d1d1";
                    borderColor = "#a0a0a0";
                    borderWidth = 2;
                  }
                }

                if (feedback) {
                  const isCorrect = key === quiz.CorrectOption;

                  if (selected === key && isCorrect) {
                    // ✅ richtig ausgewählt
                    bgColor = "#4CAF5020";
                    borderColor = "#4CAF50";
                    borderWidth = 2;
                  } else if (selected === key && !isCorrect) {
                    // ❌ falsch ausgewählt
                    bgColor = "#E5393520";
                    borderColor = "#E53935";
                    borderWidth = 2;
                  } else if (isCorrect && selected !== key) {
                    // ✅ richtige, aber nicht gewählte Option
                    bgColor = theme.colors.card;
                    borderColor = "#4CAF50";
                    borderWidth = 1.5;
                  }
                }

                return { backgroundColor: bgColor, borderColor, borderWidth };
              })(),
            ]}
            onPress={() => onSelect(key)}
            disabled={!!feedback}
          >
            <Text
              style={[
                styles.optionText,
                { color: theme.colors.text, textAlign: "center" },
              ]}
            >
              {hyphenateLabel(
                key === "A"
                  ? quiz.OptionA
                  : key === "B"
                    ? quiz.OptionB
                    : quiz.OptionC,
              )}
            </Text>
          </TouchableOpacity>
        ))}
      </View>
    </ScrollView>
  );
}

const styles = StyleSheet.create({
  container: {
    flex: 1,
    justifyContent: "center",
    alignItems: "center",
    paddingHorizontal: dynamicSpacing(10, 30),
  },
  question: {
    fontFamily: "Lato-Bold",
    fontSize: scaleFont(20),
    textAlign: "center",
    marginBottom: dynamicSpacing(40, 50),
  },
  optionsContainer: {
    width: "90%",
    gap: dynamicSpacing(16, 22),
  },
  optionButton: {
    paddingVertical: dynamicSpacing(18, 26),
    paddingHorizontal: dynamicSpacing(16, 26),
    borderRadius: isTablet ? 14 : 12,
    borderWidth: 1.5,
    alignItems: "center",
  },
  optionText: {
    fontFamily: "Montserrat-Regular",
    fontSize: scaleFont(18),
    textAlign: "center",
  },
});
