// app/Training/QuizTrueFalseSlide.tsx

import { useTheme } from "@/app/context/ThemeContext";
import { demoQuizTrueFalse } from "@/app/data/demoQuizTrueFalse";
import { getImageByKey } from "@/app/utils/imageMappings";
import {
  cappedWidth,
  dynamicSpacing,
  isTablet,
  scaleFont,
  useOrientation,
} from "@/app/utils/responsive";

import { useEffect, useState } from "react";
import {
  Image,
  ScrollView,
  StyleSheet,
  Text,
  TouchableOpacity,
  View,
} from "react-native";

interface QuizTrueFalseSlideProps {
  quizId: number;
  selected: boolean | null;
  onSelect: (v: boolean) => void;
  confirmRequested: boolean;
  onConfirmed: () => void;
  onResult: (correctCount: number, totalCount: number) => void;
  onFeedback: (text: string) => void;
}

export default function QuizTrueFalseSlide({
  quizId,
  selected,
  onSelect,
  confirmRequested,
  onConfirmed,
  onResult,
  onFeedback,
}: QuizTrueFalseSlideProps) {
  const { theme } = useTheme();
  const isDarkMode = theme.dark === true;
  const { width, height } = useOrientation();
  const isWide = width >= 768;

  const [quiz, setQuiz] = useState<{
    Statement: string;
    CorrectValue: boolean;
    ImagePath?: string | null;
  } | null>(null);

  const [feedback, setFeedback] = useState<string>("");

  useEffect(() => {
    const loadQuiz = async () => {
      const data = demoQuizTrueFalse.find((q) => q.QuizId === quizId) ?? null;
      setQuiz(data);
      setFeedback("");
    };
    loadQuiz();
  }, [quizId]);

  // Wenn Bestätigen gedrückt wurde → prüfen
  useEffect(() => {
    if (confirmRequested && selected !== null && quiz) {
      const correct = selected === quiz.CorrectValue;
      const message = correct ? "Gut gemacht!" : "Leider falsch.";
      setFeedback(message);
      onFeedback(message);
      onResult(correct ? 1 : 0, 1);
      onConfirmed();
    }
  }, [confirmRequested]);

  if (!quiz) return null;

  return (
    <ScrollView
      contentContainerStyle={[
        styles.container,
        {
          backgroundColor: theme.colors.background,
          flexGrow: 1,
          paddingTop: isWide ? dynamicSpacing(20, 30) : dynamicSpacing(40, 60),
          paddingBottom: isWide
            ? dynamicSpacing(40, 60)
            : dynamicSpacing(80, 100),
        },
      ]}
      showsVerticalScrollIndicator={false}
    >
      <Text style={[styles.question, { color: theme.colors.text }]}>
        {quiz.Statement}
      </Text>
      {quiz?.ImagePath && (
        <View
          style={[
            styles.imageWrapper,
            {
              backgroundColor: isDarkMode
                ? "rgba(250, 245, 255, 0.75)"
                : "transparent",

              borderRadius: 12,
              padding: dynamicSpacing(10, 14),
            },
          ]}
        >
          <Image
            source={getImageByKey(quiz.ImagePath)}
            style={[
              styles.image,
              isWide
                ? {
                    width: cappedWidth * 0.85,
                    height: height * 0.3,
                    maxHeight: 240,
                  }
                : {
                    width: cappedWidth * 0.8,
                    height: cappedWidth * 0.45,
                    maxHeight: 320,
                  },
            ]}
            resizeMode="contain"
          />
        </View>
      )}

      <View style={styles.buttonsContainer}>
        {[
          { label: "Wahr", value: true },
          { label: "Falsch", value: false },
        ].map(({ label, value }) => {
          const isSelected = selected === value;
          const isCorrect = !!feedback && value === quiz.CorrectValue;
          const isWrong = feedback && isSelected && !isCorrect;
          let bgColor = theme.colors.card;
          let borderColor = theme.colors.border;

          if (isSelected && !feedback) {
            if (isDarkMode) {
              // Darkmode: wie bisher
              bgColor = theme.colors.card;
              borderColor = "#d1d1d1";
            } else {
              // Lightmode: gut sichtbares Grau
              bgColor = "#d1d1d1";
              borderColor = "#a0a0a0";
            }
          }

          if (feedback) {
            const correct = value === quiz.CorrectValue;

            if (isSelected && correct) {
              bgColor = "#4CAF5020";
              borderColor = "#4CAF50";
            } else if (isSelected && !correct) {
              bgColor = "#E5393520";
              borderColor = "#E53935";
            } else if (correct && !isSelected) {
              bgColor = theme.colors.card;
              borderColor = "#4CAF50";
            }
          }

          return (
            <TouchableOpacity
              key={label}
              style={[
                styles.button,
                {
                  backgroundColor: bgColor,
                  borderColor,
                  borderWidth: isSelected && !feedback ? 2 : 1.5, // dicker Rand bei Auswahl
                },
              ]}
              onPress={() => onSelect(value)}
              disabled={!!feedback}
            >
              <Text style={[styles.buttonText, { color: theme.colors.text }]}>
                {label}
              </Text>
            </TouchableOpacity>
          );
        })}
      </View>
    </ScrollView>
  );
}

const styles = StyleSheet.create({
  container: {
    flex: 1,
    justifyContent: "flex-start",
    alignItems: "center",
    padding: dynamicSpacing(20, 30),
  },
  question: {
    fontFamily: "Lato-Bold",
    fontSize: scaleFont(20),
    textAlign: "center",
    marginTop: dynamicSpacing(20, 10), // vorher 80,40 → kleiner
    marginBottom: dynamicSpacing(20, 30), // etwas kompakter
    paddingHorizontal: dynamicSpacing(24, 40),
  },
  imageWrapper: {
    flexGrow: 0,
    justifyContent: "center",
    alignItems: "center",
    marginVertical: dynamicSpacing(20, 30), // vorher 40,50 → halbiert
    padding: 12,
    borderRadius: 12,
  },
  image: {
    resizeMode: "contain",
  },
  buttonsContainer: {
    flexDirection: "row",
    justifyContent: "space-around",
    width: "80%",
    marginBottom: dynamicSpacing(6, 16), // vorher 30,40 → enger
  },
  button: {
    borderWidth: 1.5,
    borderRadius: isTablet ? 10 : 8,
    paddingVertical: dynamicSpacing(8, 12),
    paddingHorizontal: dynamicSpacing(20, 28),
  },
  buttonText: {
    fontFamily: "Montserrat-Bold",
    fontSize: scaleFont(18),
    color: "#fff",
  },
});
